{
  "prose": [
    {
      "key": "headline",
      "text": "Select {arm:atlas-m}. It satisfies all quality gates and latency budgets at lower cost than {arm:atlas-l}."
    },
    {
      "key": "lede",
      "text": "{arm:atlas-m} is the only evaluated model that meets every quality and p95 latency threshold across tasks. Lowering the p95 latency budget or accepting quality breaches on multi-turn tasks would be required to consider smaller candidates."
    },
    {
      "key": "decision.recommendation",
      "text": "Adopt {arm:atlas-m} across all concierge flows."
    },
    {
      "key": "decision.why_not",
      "text": "{arm:atlas-l} breaches the p95 latency budget of {criteria.p95.threshold}s in multi-turn troubleshooting and research at substantially higher cost; {arm:open-70b} and {arm:brisk-s} breach multiple task quality floors."
    },
    {
      "key": "decision.watch",
      "text": "Weakest margin: {weakest.arm} achieves {weakest.value} against {weakest.criterion} at {weakest.threshold}, leaving a margin of {weakest.margin}. Monitor issue resolution on long multi-turn interactions."
    },
    {
      "key": "decision.next",
      "text": "Run a targeted trial of {arm:atlas-m} on live troubleshooting traffic to verify resolution rates under variable user turns."
    },
    {
      "key": "summary.0.title",
      "text": "Billing task cost comparison"
    },
    {
      "key": "summary.1.title",
      "text": "Billing task latency comparison"
    },
    {
      "key": "sections.gate_matrix.eyebrow",
      "text": "Gate compliance"
    },
    {
      "key": "sections.gate_matrix.headline",
      "text": "{arm:atlas-m} passes all gates while cheaper models fail quality floors"
    },
    {
      "key": "sections.gate_matrix.takeaway",
      "text": "Green cells indicate passing both quality floors and latency thresholds across evaluated domains."
    },
    {
      "key": "sections.gate_matrix.title",
      "text": "Task-level gate status by model"
    },
    {
      "key": "sections.gate_matrix.caption",
      "text": ""
    },
    {
      "key": "sections.latency_comparison.eyebrow",
      "text": "Latency constraints"
    },
    {
      "key": "sections.latency_comparison.headline",
      "text": "{arm:atlas-l} exceeds tail latency budgets in multi-turn tasks"
    },
    {
      "key": "sections.latency_comparison.takeaway",
      "text": "Bars show measured p95 response times compared against the budget limit."
    },
    {
      "key": "sections.latency_comparison.title",
      "text": "Tail latency in troubleshooting and research tasks"
    },
    {
      "key": "sections.latency_comparison.caption",
      "text": ""
    },
    {
      "key": "durable_claims.0",
      "text": "{arm:atlas-m} meets issue resolution at {task.trouble.atlas-m.resolves.mean}%, while {arm:atlas-l} reaches {task.trouble.atlas-l.latency_s.p95}s p95 latency."
    },
    {
      "key": "method.0.term",
      "text": "Cases and repeats"
    },
    {
      "key": "method.0.text",
      "text": "Evaluated across {scoreboard.atlas-m.cases} distinct task scenarios with fixed prompts across all four model candidates."
    },
    {
      "key": "method.1.term",
      "text": "Judge calibration"
    },
    {
      "key": "method.1.text",
      "text": "Quality dimensions judged with calibrated evaluator showing {judged.overall.agreement} agreement across {judged.overall.calibration_ratings} ratings."
    },
    {
      "key": "method.2.term",
      "text": "Gates and budgets"
    },
    {
      "key": "method.2.text",
      "text": "Models must satisfy both task quality minimums and a p95 latency ceiling of {criteria.p95.threshold}s."
    },
    {
      "key": "method.3.term",
      "text": "Cost basis"
    },
    {
      "key": "method.3.text",
      "text": "Costs computed from observed token consumption and published provider pricing per 1,000 interactions."
    },
    {
      "key": "explore.title",
      "text": "Explore constraints"
    },
    {
      "key": "explore.recomputes",
      "text": "Adjusting the p95 latency budget shifts whether {arm:atlas-l} passes gates, but {arm:atlas-m} remains dominant on cost."
    },
    {
      "key": "explore.controls.p95_budget.title",
      "text": "Latency budget (p95)"
    }
  ]
}

